SELECT COUNT(1)
FROM ai_policy_chunk
WHERE base_id = #{baseId}

SELECT chunk.id AS chunk_id, chunk.document_id, doc.name AS doc_title, doc.region_scope AS policy_region, chunk.title AS heading_path, chunk.content AS snippet, chunk.policy_aliases AS keyword_text, chunk.region_scope, chunk.doc_type, chunk.topic_type, chunk.policy_name, chunk.policy_aliases, NULL AS policy_no, chunk.title AS chapter_title, chunk.title AS section_title, chunk.source_scene AS scene_priority, chunk.enabled AS searchable, chunk.sort_no AS chunk_no FROM ai_policy_chunk chunk INNER JOIN ai_policy_document doc ON doc.id = chunk.document_id WHERE chunk.base_id = #{query.baseId}
AND chunk.enabled = #{query.enabled}
AND chunk.policy_key = #{query.policyKey}
AND chunk.policy_key IN
#{item}
AND chunk.region_scope IN
#{item}
AND chunk.doc_type IN
#{item}
AND chunk.topic_type IN
#{item}
AND chunk.question_type IN
#{item}
AND ( chunk.title LIKE '%' || #{query.keywords} || '%' OR chunk.content LIKE '%' || #{query.keywords} || '%' OR COALESCE(chunk.policy_name, '') LIKE '%' || #{query.keywords} || '%' OR COALESCE(chunk.policy_aliases, '') LIKE '%' || #{query.keywords} || '%' OR COALESCE(doc.name, '') LIKE '%' || #{query.keywords} || '%' )
ORDER BY chunk.priority DESC, chunk.sort_no ASC, chunk.id ASC LIMIT #{query.topN}
